def step(grid, birth, survive, outside="wall"):
    if not grid or not grid[0]:
        raise ValueError("the grid is empty")
    height = len(grid)
    width = len(grid[0])
    if any(len(row) != width for row in grid):
        raise ValueError("the grid is ragged")
    if outside not in ("wall", "open", "wrap"):
        raise ValueError(f"unknown boundary {outside!r}")
    birth = set(birth)
    survive = set(survive)

    def at(x, y):
        if 0 <= x < width and 0 <= y < height:
            return grid[y][x]
        if outside == "wall":
            return 1
        if outside == "open":
            return 0
        return grid[y % height][x % width]

    out = []
    for y in range(height):
        row = []
        for x in range(width):
            count = 0
            for dy in (-1, 0, 1):
                for dx in (-1, 0, 1):
                    if dx or dy:
                        count += at(x + dx, y + dy)
            if grid[y][x]:
                row.append(1 if count in survive else 0)
            else:
                row.append(1 if count in birth else 0)
        out.append(row)
    return out
